using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_PlayerTarget", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_PlayerTarget")]
public class DiceSecondActionLogic_PlayerTarget : DiceSecondActionLogic
{
	[Header("Player Game Object Reference")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		actionFace.SecondBattleAction.CastTargetAmount(playerGameObjectReference.value, actionFace.SecondModifiedActionValue, source);
	}
}
